import React, { useState, useEffect } from "react";
import axios from "axios";
import { getBaseURL } from "../apiConfig";
import "./AdminOrderList.scss";

const AdminOrderList = (props) => {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = () => {
    axios
      .get(`${getBaseURL()}api/orders`)
      .then((res) => {
        const data = res.data;
        setOrders(data);
      })
      .catch((err) => console.log("Couldn't receive order list"));
  };

  const validateOrder = (orderId) => {
    axios
      .put(`${getBaseURL()}api/orders/validate/${orderId}`)
      .then(() => {
        alert("Order validated successfully.");
        fetchOrders(); // Rafraîchir la liste des commandes
      })
      .catch((err) => console.log("Couldn't validate order"));
  };

  const deleteOrder = (orderId) => {
    axios
      .delete(`${getBaseURL()}api/orders/delete/${orderId}`)
      .then(() => {
        alert("Order deleted successfully.");
        fetchOrders(); // Rafraîchir la liste des commandes
      })
      .catch((err) => console.log("Couldn't delete order"));
  };

  const openOrderDetails = (order) => {
    props.handleOrderDetails(order);
  };

  return (
    <div>
      <div>
        <h1>Order List</h1>
      </div>
      <table>
        <thead>
          <tr>
            <th>Id</th>
            <th>Customer Name</th>
            <th>Order Date</th>
            <th>Price</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((order) => (
            <tr key={order.orderId}>
              <td>{order.orderId}</td>
              <td>{order.fname}</td>
              <td>{order.createdDate}</td>
              <td>{order.totalPrice}</td>
              <td>{order.status}</td>
              <td>
                <button onClick={() => openOrderDetails(order)}>Details</button>
                {order.status === "pending" && (
                  <>
                    <button onClick={() => validateOrder(order.orderId)}>Validate</button>
                    <button onClick={() => deleteOrder(order.orderId)}>Delete</button>
                  </>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default AdminOrderList;
